input.content:
package hclx

// TokenType identifies the kind of a scanned token in the HCL native syntax.
type TokenType int

// The token kinds produced by Scan. The set mirrors the HCL native syntax
// grammar closely enough that the formatter can make layout decisions from
// token types alone.
const (
	TokenInvalid TokenType = iota
	TokenEOF
	TokenNewline
	TokenComment

	TokenIdent
	TokenNumberLit

	TokenOQuote    // opening " of a quoted template
	TokenCQuote    // closing " of a quoted template
	TokenQuotedLit // literal run inside a quoted template

	TokenOHeredoc  // <<EOT or <<-EOT including its newline
	TokenCHeredoc  // the heredoc terminator identifier
	TokenStringLit // literal run inside a heredoc

	TokenTemplateInterp  // ${
	TokenTemplateControl // %{
	TokenTemplateSeqEnd  // } closing an interpolation/control sequence

	TokenOBrace
	TokenCBrace
	TokenOBrack
	TokenCBrack
	TokenOParen
	TokenCParen

	TokenComma
	TokenDot
	TokenEllipsis
	TokenColon
	TokenQuestion
	TokenFatArrow

	TokenEqual
	TokenEqualOp
	TokenNotEqual
	TokenLessThan
	TokenLessThanEq
	TokenGreaterThan
	TokenGreaterThanEq

	TokenPlus
	TokenMinus
	TokenStar
	TokenSlash
	TokenPercent

	TokenAnd
	TokenOr
	TokenBang
)

// Token is a single scanned token along with the amount of horizontal
// whitespace that preceded it. The formatter rewrites SpacesBefore in place.
type Token struct {
	Type         TokenType
	Bytes        []byte
	SpacesBefore int

	// Line and Column of the first byte of the token, 1-based.
	Line, Column int
	// Byte is the offset of the first byte of the token within the source.
	Byte int
}

// Tokens is a sequence of tokens.
type Tokens []*Token

var nilToken = &Token{Type: TokenInvalid}

func (t TokenType) isOpenBracket() bool {
	switch t {
	case TokenOBrace, TokenOBrack, TokenOParen, TokenTemplateControl, TokenTemplateInterp:
		return true
	}
	return false
}

func (t TokenType) isCloseBracket() bool {
	switch t {
	case TokenCBrace, TokenCBrack, TokenCParen, TokenTemplateSeqEnd:
		return true
	}
	return false
}

func bracketChange(t *Token) int {
	switch {
	case t.Type.isOpenBracket():
		return 1
	case t.Type.isCloseBracket():
		return -1
	}
	return 0
}

