package hclx

import (
	"unicode"
	"unicode/utf8"
)

// Scan converts src into a token sequence. Scanning never fails: byte runs that
// cannot be interpreted are emitted as TokenInvalid so that callers such as the
// formatter can still operate on malformed input.
func Scan(src []byte) Tokens {
	s := &scanner{src: src, line: 1, col: 1}
	s.stack = []frame{{mode: modeNormal}}
	s.run()
