type frame struct {
	mode scanMode
	// braces counts the unbalanced "{" seen inside a template interpolation.
	braces int
	// interp reports whether the frame was entered from a template, meaning a
	// balancing "}" terminates it.
	interp bool
	// marker is the heredoc terminator identifier.
	marker []byte
	// indented reports a <<- heredoc.
