func (s *scanner) top() *frame { return &s.stack[len(s.stack)-1] }

func (s *scanner) run() {
	for s.pos < len(s.src) {
		switch s.top().mode {
		case modeNormal:
			s.scanNormal()
		case modeTemplate:
			s.scanTemplate()
		case modeHeredoc:
			s.scanHeredoc()
