// advance moves the read position forward by n bytes, tracking the line and
// column of the cursor.
func (s *scanner) advance(n int) {
	for i := 0; i < n; {
		r, sz := utf8.DecodeRune(s.src[s.pos+i:])
		if sz == 0 {
			break
