// emit appends a token covering src[start:start+n], assuming the cursor is
// currently at start.
func (s *scanner) emit(t TokenType, start, n int) {
	tok := &Token{
		Type:         t,
		Bytes:        s.src[start : start+n],
		SpacesBefore: s.pending,
		Line:         s.line,
		Column:       s.col,
		Byte:         start,
	}
	s.pending = 0
	s.toks = append(s.toks, tok)
	s.advance(n)
