func (s *scanner) scanNormal() {
	s.skipSpaces()
	if s.pos >= len(s.src) {
		return
	}
	start := s.pos
	c := s.src[s.pos]
	switch {
	case c == '\n':
		s.emit(TokenNewline, start, 1)
		return
	case c == '\r' && s.pos+1 < len(s.src) && s.src[s.pos+1] == '\n':
		s.emit(TokenNewline, start, 2)
		return
	case c == '#':
		s.emit(TokenComment, start, s.lineCommentLen(1))
		return
	case c == '/' && s.peek(1) == '/':
		s.emit(TokenComment, start, s.lineCommentLen(2))
		return
	case c == '/' && s.peek(1) == '*':
		s.emit(TokenComment, start, s.blockCommentLen())
		return
	case c == '"':
		s.emit(TokenOQuote, start, 1)
