		switch t {
		case TokenOBrace:
			s.top().braces++
		case TokenCBrace:
			f := s.top()
			if f.interp && f.braces == 0 {
				s.emit(TokenTemplateSeqEnd, start, 1)
				s.stack = s.stack[:len(s.stack)-1]
				return
			}
			if f.braces > 0 {
				f.braces--
			}
