func (s *scanner) peek(off int) byte {
	if s.pos+off < len(s.src) {
		return s.src[s.pos+off]
	}
	return 0
}

func (s *scanner) runeAt(off int) rune {
	r, _ := utf8.DecodeRune(s.src[s.pos+off:])
	return r
}

func (s *scanner) lineCommentLen(skip int) int {
	i := s.pos + skip
	for i < len(s.src) && s.src[i] != '\n' {
		i++
	}
	if i < len(s.src) {
		i++ // the terminating newline belongs to the comment token
	}
	return i - s.pos
}

func (s *scanner) blockCommentLen() int {
	i := s.pos + 2
	for i < len(s.src) {
		if s.src[i] == '*' && i+1 < len(s.src) && s.src[i+1] == '/' {
			return i + 2 - s.pos
		}
		i++
	}
	return len(s.src) - s.pos
}

func (s *scanner) numberLen() int {
	i := s.pos
	for i < len(s.src) && isDigit(s.src[i]) {
		i++
	}
	if i < len(s.src) && s.src[i] == '.' && i+1 < len(s.src) && isDigit(s.src[i+1]) {
		i++
		for i < len(s.src) && isDigit(s.src[i]) {
			i++
		}
	}
	if i < len(s.src) && (s.src[i] == 'e' || s.src[i] == 'E') {
		j := i + 1
		if j < len(s.src) && (s.src[j] == '+' || s.src[j] == '-') {
			j++
		}
		if j < len(s.src) && isDigit(s.src[j]) {
			for j < len(s.src) && isDigit(s.src[j]) {
