// heredocHeader recognizes "<<MARKER\n" and "<<-MARKER\n".
func (s *scanner) heredocHeader() (int, frame, bool) {
	i := s.pos + 2
	f := frame{mode: modeHeredoc}
	if i < len(s.src) && s.src[i] == '-' {
		f.indented = true
