		return 0, f, false
	}
	f.marker = s.src[start:i]
	for i < len(s.src) && (s.src[i] == ' ' || s.src[i] == '\t' || s.src[i] == '\r') {
		i++
	}
	if i >= len(s.src) || s.src[i] != '\n' {
