// scanTemplate handles the interior of a quoted template.
func (s *scanner) scanTemplate() {
	start := s.pos
	if s.src[s.pos] == '"' {
		s.emit(TokenCQuote, start, 1)
		s.stack = s.stack[:len(s.stack)-1]
		return
	}
	if n, t, ok := s.templateOpener(); ok {
		s.emit(t, start, n)
		s.stack = append(s.stack, frame{mode: modeNormal, interp: true})
		return
	}
	i := s.pos
	for i < len(s.src) {
		switch s.src[i] {
		case '"':
			s.emit(TokenQuotedLit, start, i-start)
			return
		case '\\':
			i += 2
			continue
		case '\n':
			// An unterminated quoted template: stop the literal here so the
			// newline is not swallowed.
			if i == start {
				s.emit(TokenInvalid, start, 1)
				s.stack = s.stack[:len(s.stack)-1]
				return
			}
			s.emit(TokenQuotedLit, start, i-start)
			return
		case '$', '%':
			if i+1 < len(s.src) && s.src[i+1] == s.src[i] {
				i += 2
				continue
			}
			if i+1 < len(s.src) && s.src[i+1] == '{' {
				if i == start {
					// handled by templateOpener above
					i += 2
					continue
				}
				s.emit(TokenQuotedLit, start, i-start)
				return
			}
		}
		i++
	}
	s.emit(TokenQuotedLit, start, len(s.src)-start)
	s.stack = s.stack[:len(s.stack)-1]
}

func (s *scanner) templateOpener() (int, TokenType, bool) {
	if s.pos+1 >= len(s.src) || s.src[s.pos+1] != '{' {
		return 0, 0, false
	}
	switch s.src[s.pos] {
	case '$':
		n := 2
		if s.pos+2 < len(s.src) && s.src[s.pos+2] == '~' {
			n = 3
		}
		return n, TokenTemplateInterp, true
	case '%':
		n := 2
		if s.pos+2 < len(s.src) && s.src[s.pos+2] == '~' {
			n = 3
		}
		return n, TokenTemplateControl, true
	}
	return 0, 0, false
}

// scanHeredoc consumes one line of a heredoc body, or its terminator.
func (s *scanner) scanHeredoc() {
	f := s.top()
	start := s.pos
	// Check whether the current line is the terminator.
	i := s.pos
	for i < len(s.src) && (s.src[i] == ' ' || s.src[i] == '\t') {
		i++
	}
	if hasPrefixAt(s.src, i, f.marker) {
		j := i + len(f.marker)
		k := j
		for k < len(s.src) && (s.src[k] == ' ' || s.src[k] == '\t' || s.src[k] == '\r') {
			k++
		}
		if k >= len(s.src) || s.src[k] == '\n' {
			if i > start {
				s.emit(TokenStringLit, start, i-start)
			}
			s.emit(TokenCHeredoc, s.pos, len(f.marker))
			s.stack = s.stack[:len(s.stack)-1]
			return
		}
	}
	if n, t, ok := s.templateOpener(); ok {
		s.emit(t, start, n)
		s.stack = append(s.stack, frame{mode: modeNormal, interp: true})
		return
	}
	i = s.pos
	for i < len(s.src) {
		if s.src[i] == '\n' {
			i++
			break
		}
		if (s.src[i] == '$' || s.src[i] == '%') && i+1 < len(s.src) && s.src[i+1] == s.src[i] {
			i += 2
			continue
		}
		if (s.src[i] == '$' || s.src[i] == '%') && i+1 < len(s.src) && s.src[i+1] == '{' && i > s.pos {
			break
		}
		i++
	}
	if i == s.pos {
		i = len(s.src)
	}
	s.emit(TokenStringLit, start, i-s.pos)
	if s.pos >= len(s.src) {
		s.stack = s.stack[:len(s.stack)-1]
	}
}

func hasPrefixAt(src []byte, at int, pre []byte) bool {
	if at+len(pre) > len(src) {
		return false
	}
	for i := range pre {
		if src[at+i] != pre[i] {
			return false
		}
	}
	return true
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isIDStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) && false || unicode.In(r, unicode.Nl, unicode.Other_ID_Start)
}

func isIDContinue(r rune) bool {
	return r == '_' || r == '-' || unicode.IsLetter(r) || unicode.IsDigit(r) ||
		unicode.In(r, unicode.Nl, unicode.Mn, unicode.Mc, unicode.Pc, unicode.Other_ID_Start, unicode.Other_ID_Continue)
}

