package hclx

import (
	"bytes"
	"unicode"
	"unicode/utf8"
)

// Format rewrites src into the canonical HCL layout: two-space indentation per
// nesting level, canonical spacing between tokens, and "=" signs aligned across
// runs of consecutive single-line attribute definitions.
//
// Format works purely on tokens, so malformed input is reformatted rather than
// rejected.
func Format(src []byte) []byte {
	toks := Scan(src)
	formatTokens(toks)
	var buf bytes.Buffer
	for _, t := range toks {
		if t.Type == TokenEOF {
			continue
		}
		for i := 0; i < t.SpacesBefore; i++ {
			buf.WriteByte(' ')
		}
		buf.Write(t.Bytes)
	}
	return buf.Bytes()
}

// formatLine holds one source line split into the three alignment cells used by
// the layout algorithm.
type formatLine struct {
	lead    Tokens
	assign  Tokens
	comment Tokens
}

func formatTokens(toks Tokens) {
	lines := linesForFormat(toks)
	formatIndent(lines)
	formatSpaces(lines)
	formatCells(lines)
}

// isNewline reports whether the token terminates a line. Single-line comments
// consume their trailing newline, so they count too.
func isNewline(t *Token) bool {
	if t.Type == TokenNewline {
		return true
	}
	if t.Type == TokenComment && len(t.Bytes) > 0 && t.Bytes[len(t.Bytes)-1] == '\n' {
		return true
	}
	return false
}

func linesForFormat(toks Tokens) []formatLine {
	if len(toks) == 0 {
		return nil
	}
	count := 1
	for _, t := range toks {
		if isNewline(t) {
			count++
		}
	}
	lines := make([]formatLine, count)
	li, start := 0, 0
	for i, t := range toks {
		if t.Type == TokenEOF {
			lines[li].lead = toks[start:i]
			break
		}
		if isNewline(t) {
			lines[li].lead = toks[start : i+1]
			start = i + 1
			li++
		}
	}
	// Split trailing comments and single-line attribute values into their own
	// cells so they can be aligned independently.
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if len(line.lead) > 1 && line.lead[len(line.lead)-1].Type == TokenComment {
			line.comment = line.lead[len(line.lead)-1:]
			line.lead = line.lead[:len(line.lead)-1]
		}
		for j, t := range line.lead {
			if j > 0 && t.Type == TokenEqual {
				// Only treat the remainder as a value cell when it is a
				// complete expression; a net-positive bracket count means the
				// expression continues onto later lines.
				net := 0
				for _, tt := range line.lead[j:] {
					net += bracketChange(tt)
				}
				if net == 0 {
					line.assign = line.lead[j:]
					line.lead = line.lead[:j]
				}
				break
			}
		}
	}
	return lines
}

func formatIndent(lines []formatLine) {
	// Indentation is tracked with a stack recording how many brackets each
	// level opened, so that lines closing several brackets at once dedent by
	// the right number of levels even when the input is unbalanced.
	indents := make([]int, 0, 10)
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if line.lead[0].Type == TokenNewline {
			line.lead[0].SpacesBefore = 0
			continue
		}
		net := 0
		for _, t := range line.lead {
			net += bracketChange(t)
		}
		for _, t := range line.assign {
			net += bracketChange(t)
		}
		switch {
		case net > 0:
			line.lead[0].SpacesBefore = 2 * len(indents)
			indents = append(indents, net)
		case net < 0:
			closed := -net
			for closed > 0 && len(indents) > 0 {
				last := indents[len(indents)-1]
				switch {
				case closed > last:
					closed -= last
					indents = indents[:len(indents)-1]
				case closed < last:
					indents[len(indents)-1] -= closed
					closed = 0
				default:
					indents = indents[:len(indents)-1]
					closed = 0
				}
			}
			line.lead[0].SpacesBefore = 2 * len(indents)
		default:
			line.lead[0].SpacesBefore = 2 * len(indents)
		}
	}
}

func formatSpaces(lines []formatLine) {
	for _, line := range lines {
		for _, cell := range []Tokens{line.lead, line.assign, line.comment} {
			for i, t := range cell {
				before, after := nilToken, nilToken
				if i > 0 {
					before = cell[i-1]
				}
				if i < len(cell)-1 {
					after = cell[i+1]
				}
				if spaceAfterToken(t, before, after) {
					after.SpacesBefore = 1
				} else if after != nilToken {
					after.SpacesBefore = 0
				}
			}
		}
	}
}

// spaceAfterToken decides whether subject should be followed by a single space,
// given its neighbours within the same cell.
func spaceAfterToken(subject, before, after *Token) bool {
	switch {
	case after.Type == TokenNewline || after.Type == TokenInvalid && after == nilToken:
		return false

	case subject.Type == TokenIdent && after.Type == TokenOParen:
		// Keep a function name attached to its argument list.
		return false

	case subject.Type == TokenDot || after.Type == TokenDot:
		return false

	case after.Type == TokenComma || after.Type == TokenEllipsis:
		return false

	case subject.Type == TokenComma:
		return true

	case subject.Type == TokenQuotedLit || subject.Type == TokenStringLit ||
		subject.Type == TokenOQuote || subject.Type == TokenOHeredoc ||
		after.Type == TokenQuotedLit || after.Type == TokenStringLit ||
		after.Type == TokenCQuote || after.Type == TokenCHeredoc:
		// Templates are reproduced exactly as written.
		return false

	case isInKeyword(subject) && before.Type == TokenIdent:
		// "for x in [y]" reads better with a space, even though "in" looks
		// like a variable being indexed.
		return true

	case after.Type == TokenOBrack &&
		(subject.Type == TokenIdent || subject.Type == TokenNumberLit || bracketChange(subject) < 0):
		return false

	case subject.Type == TokenMinus:
		// A minus is negation rather than subtraction when the token before it
		// cannot end an expression.
		switch before.Type {
		case TokenOParen, TokenOBrace, TokenOBrack, TokenEqual, TokenColon, TokenComma, TokenQuestion,
			TokenPlus, TokenStar, TokenSlash, TokenPercent, TokenMinus,
			TokenEqualOp, TokenNotEqual, TokenGreaterThan, TokenGreaterThanEq,
			TokenLessThan, TokenLessThanEq, TokenAnd, TokenOr, TokenBang:
			return false
		}
		if before == nilToken {
			return false
		}
		return true

	case subject.Type == TokenOBrace || after.Type == TokenCBrace:
		// Braces are spaced on both sides, both for single-line blocks and for
		// object constructors -- except when the pair is empty.
		if subject.Type == TokenOBrace && after.Type == TokenCBrace {
			return false
		}
		return true

	case bracketChange(subject) > 0:
		return false

	case bracketChange(after) < 0:
		return false

	default:
		return true
	}
}

func isInKeyword(t *Token) bool {
	return t.Type == TokenIdent && string(t.Bytes) == "in"
}

func formatCells(lines []formatLine) {
	chainStart := -1
	maxCols := 0

	closeAssign := func(end int) {
		for i := chainStart; i < end; i++ {
			cols := columns(lines[i].lead)
			lines[i].assign[0].SpacesBefore = (maxCols - cols) + 1
		}
		chainStart, maxCols = -1, 0
	}
	for i := range lines {
		if lines[i].assign == nil {
			if chainStart != -1 {
				closeAssign(i)
			}
			continue
		}
		if chainStart == -1 {
			chainStart = i
		}
		if c := columns(lines[i].lead); c > maxCols {
			maxCols = c
		}
	}
	if chainStart != -1 {
		closeAssign(len(lines))
	}

	closeComment := func(end int) {
		for i := chainStart; i < end; i++ {
			cols := columns(lines[i].lead) + columns(lines[i].assign)
			lines[i].comment[0].SpacesBefore = (maxCols - cols) + 1
		}
		chainStart, maxCols = -1, 0
	}
	for i := range lines {
		if lines[i].comment == nil {
			if chainStart != -1 {
				closeComment(i)
			}
			continue
		}
		if chainStart == -1 {
			chainStart = i
		}
		if c := columns(lines[i].lead) + columns(lines[i].assign); c > maxCols {
			maxCols = c
		}
	}
	if chainStart != -1 {
		closeComment(len(lines))
	}
}

// columns is the printed width of a token sequence, counting grapheme-ish
// clusters so that combining marks do not inflate alignment.
func columns(ts Tokens) int {
	n := 0
	for _, t := range ts {
		n += t.SpacesBefore
		n += textWidth(t.Bytes)
	}
	return n
}

func textWidth(b []byte) int {
	n := 0
	for len(b) > 0 {
		r, sz := utf8.DecodeRune(b)
		if sz == 0 {
			break
		}
		if !unicode.Is(unicode.Mn, r) && !unicode.Is(unicode.Me, r) {
			n++
		}
		b = b[sz:]
	}
	return n
}

