// columns is the printed width of a token sequence, counting grapheme-ish
// clusters so that combining marks do not inflate alignment.
func columns(ts Tokens) int {
	n := 0
	for _, t := range ts {
		n += t.SpacesBefore
		n += textWidth(t.Bytes)
	}
	return n
}

func textWidth(b []byte) int {
	n := 0
	for len(b) > 0 {
		r, sz := utf8.DecodeRune(b)
		if sz == 0 {
			break
		}
		if !unicode.Is(unicode.Mn, r) && !unicode.Is(unicode.Me, r) {
			n++
		}
		b = b[sz:]
	}
	return n
}

