3	import (
4		"unicode"
5		"unicode/utf8"
6	)
7	
8	// Scan converts src into a token sequence. Scanning never fails: byte runs that
9	// cannot be interpreted are emitted as TokenInvalid so that callers such as the
10	// formatter can still operate on malformed input.
11	func Scan(src []byte) Tokens {
12		s := &scanner{src: src, line: 1, col: 1}
13		s.stack = []frame{{mode: modeNormal}}
14		s.run()
15		return s.toks
16	}
17	
18	type scanMode int
19	
20	const (
21		modeNormal scanMode = iota
22		modeTemplate
23		modeHeredoc
24	)
25	
26	type frame struct {
27		mode scanMode
28		// braces counts the unbalanced "{" seen inside a template interpolation.
29		braces int
30		// interp reports whether the frame was entered from a template, meaning a
31		// balancing "}" terminates it.
32		interp bool
33		// marker is the heredoc terminator identifier.
34		marker []byte
35		// indented reports a <<- heredoc.
36		indented bool
37	}
38	
39	type scanner struct {
40		src     []byte
41		pos     int
42		line    int
43		col     int
44		pending int
45		toks    Tokens
46		stack   []frame
47	}
48	
49	func (s *scanner) top() *frame { return &s.stack[len(s.stack)-1] }
50	
51	func (s *scanner) run() {
52		for s.pos < len(s.src) {
53			switch s.top().mode {
54			case modeNormal:
55				s.scanNormal()
56			case modeTemplate:
57				s.scanTemplate()
58			case modeHeredoc:
59				s.scanHeredoc()
60			}
61		}
62		s.emit(TokenEOF, s.pos, 0)
63	}
64	
65	// advance moves the read position forward by n bytes, tracking the line and
66	// column of the cursor.
67	func (s *scanner) advance(n int) {
68		for i := 0; i < n; {
69			r, sz := utf8.DecodeRune(s.src[s.pos+i:])
70			if sz == 0 {
71				break
72			}
73			if r == '\n' {
74				s.line++
75				s.col = 1
76			} else if !unicode.Is(unicode.Mn, r) && !unicode.Is(unicode.Me, r) {
77				s.col++
78			}
79			i += sz
80		}
81		s.pos += n
82	}
