// Package cli implements the small command/flag framework the atlas CLI is
// built on: nested commands, POSIX/GNU style flags, generated help and the
// usage/error rendering that goes with them.
package cli

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Value is the interface implemented by every flag's underlying storage.
type Value interface {
	String() string
	Set(string) error
	Type() string
}

// Flag describes a single command-line flag.
type Flag struct {
	Name      string
	Shorthand string
	Usage     string
	Value     Value
	DefValue  string
	// NoOptDefVal is the value assigned when the flag is given without an
	// argument, as boolean flags are.
	NoOptDefVal string
	Hidden      bool
	Changed     bool
}

// FlagSet is an ordered collection of flags.
type FlagSet struct {
	flags  []*Flag
	byName map[string]*Flag
	short  map[string]*Flag
	// Sorted reports whether help output lists the flags alphabetically rather
	// than in declaration order.
	Sorted bool
}

// NewFlagSet returns an empty flag set that lists flags alphabetically.
func NewFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, short: map[string]*Flag{}, Sorted: true}
}

// Add registers f, replacing any flag with the same name.
func (fs *FlagSet) Add(f *Flag) {
	if fs.byName == nil {
		fs.byName = map[string]*Flag{}
		fs.short = map[string]*Flag{}
	}
	if _, ok := fs.byName[f.Name]; ok {
		return
	}
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.short[f.Shorthand] = f
	}
}

// Lookup returns the flag with the given long name.
func (fs *FlagSet) Lookup(name string) *Flag {
	if fs == nil {
		return nil
	}
	return fs.byName[name]
}

// Changed reports whether the named flag was set on the command line.
func (fs *FlagSet) Changed(name string) bool {
	f := fs.Lookup(name)
	return f != nil && f.Changed
}

// HasFlags reports whether the set contains any visible flag.
func (fs *FlagSet) HasFlags() bool {
	if fs == nil {
		return false
	}
	for _, f := range fs.flags {
		if !f.Hidden {
			return true
		}
	}
	return false
}

// visible returns the flags shown in help, in display order.
func (fs *FlagSet) visible() []*Flag {
	out := make([]*Flag, 0, len(fs.flags))
	for _, f := range fs.flags {
		if !f.Hidden {
			out = append(out, f)
		}
	}
	if fs.Sorted {
		sort.SliceStable(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	}
	return out
}

// Usages renders the flag set the way the help output presents it: one flag per
// line with the descriptions aligned in a single column.
func (fs *FlagSet) Usages() string {
	type line struct {
		left  string
		right string
	}
	var lines []line
	maxlen := 0
	for _, f := range fs.visible() {
		var left string
		if f.Shorthand != "" {
			left = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			left = fmt.Sprintf("      --%s", f.Name)
		}
		name, usage := unquoteUsage(f)
		if name != "" {
			left += " " + name
		}
		if f.NoOptDefVal != "" {
			switch f.Value.Type() {
			case "string":
				left += fmt.Sprintf("[=%q]", f.NoOptDefVal)
			case "bool":
				if f.NoOptDefVal != "true" {
					left += fmt.Sprintf("[=%s]", f.NoOptDefVal)
				}
			default:
				left += fmt.Sprintf("[=%s]", f.NoOptDefVal)
			}
		}
		if len(left) > maxlen {
			maxlen = len(left)
		}
		if !defaultIsZero(f) {
			if f.Value.Type() == "string" {
				usage += fmt.Sprintf(" (default %q)", f.DefValue)
			} else {
				usage += fmt.Sprintf(" (default %s)", f.DefValue)
			}
		}
		lines = append(lines, line{left, usage})
	}
	// The description column starts one space past the widest left-hand side,
	// plus the two separator spaces.
	var b strings.Builder
	for _, l := range lines {
		b.WriteString(l.left)
		b.WriteString(strings.Repeat(" ", maxlen-len(l.left)+3))
		b.WriteString(l.right)
		b.WriteString("\n")
	}
	return b.String()
}

// unquoteUsage extracts a back-quoted placeholder name from the usage string,
// falling back to a name derived from the value's type.
func unquoteUsage(f *Flag) (name, usage string) {
	usage = f.Usage
	for i := 0; i < len(usage); i++ {
		if usage[i] != '`' {
			continue
		}
		for j := i + 1; j < len(usage); j++ {
			if usage[j] == '`' {
				name = usage[i+1 : j]
				usage = usage[:i] + name + usage[j+1:]
				return name, usage
			}
		}
		break
	}
	switch t := f.Value.Type(); t {
	case "bool":
		return "", usage
	case "float64":
		return "float", usage
	case "int64":
		return "int", usage
	case "uint64":
		return "uint", usage
	case "stringSlice":
		return "strings", usage
	case "intSlice":
		return "ints", usage
	default:
		return t, usage
	}
}

func defaultIsZero(f *Flag) bool {
	switch f.Value.(type) {
	case *boolValue:
		return f.DefValue == "false"
	case *durationValue:
		return f.DefValue == "0" || f.DefValue == "0s"
	case *intValue, *uintValue:
		return f.DefValue == "0"
	case *stringValue:
		return f.DefValue == ""
	case *stringSliceValue:
		return f.DefValue == "[]"
	}
	switch f.Value.String() {
	case "false", "<nil>", "", "0":
		return true
	}
	return false
}

// --- concrete value types ---

type stringValue struct{ p *string }

func (v *stringValue) String() string     { return *v.p }
func (v *stringValue) Set(s string) error { *v.p = s; return nil }
func (v *stringValue) Type() string       { return "string" }

type boolValue struct{ p *bool }

func (v *boolValue) String() string { return strconv.FormatBool(*v.p) }
func (v *boolValue) Set(s string) error {
	b, err := strconv.ParseBool(s)
	if err != nil {
		return fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", s)
	}
	*v.p = b
	return nil
}
func (v *boolValue) Type() string { return "bool" }

type intValue struct{ p *int }

func (v *intValue) String() string { return strconv.Itoa(*v.p) }
func (v *intValue) Set(s string) error {
	n, err := strconv.ParseInt(s, 0, 64)
	if err != nil {
		return numError(err, s, "ParseInt")
	}
	*v.p = int(n)
	return nil
}
func (v *intValue) Type() string { return "int" }

type uintValue struct{ p *uint }

func (v *uintValue) String() string { return strconv.FormatUint(uint64(*v.p), 10) }
func (v *uintValue) Set(s string) error {
	n, err := strconv.ParseUint(s, 0, 64)
	if err != nil {
		return numError(err, s, "ParseUint")
	}
	*v.p = uint(n)
	return nil
}
func (v *uintValue) Type() string { return "uint" }

func numError(err error, s, fn string) error {
	if ne, ok := err.(*strconv.NumError); ok {
		return fmt.Errorf("strconv.%s: parsing %q: %s", fn, s, ne.Err)
	}
	return err
}

type durationValue struct{ p *time.Duration }

func (v *durationValue) String() string { return v.p.String() }
func (v *durationValue) Set(s string) error {
	d, err := time.ParseDuration(s)
	if err != nil {
		return fmt.Errorf("time: invalid duration %q", s)
	}
	*v.p = d
	return nil
}
func (v *durationValue) Type() string { return "duration" }

// stringSliceValue accumulates values across repeated occurrences and splits
// each occurrence on commas, mirroring the CSV-style slice flags.
type stringSliceValue struct {
	p       *[]string
	changed bool
}

func (v *stringSliceValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v *stringSliceValue) Set(s string) error {
	parts, err := readAsCSV(s)
	if err != nil {
		return err
	}
	if !v.changed {
		*v.p = parts
		v.changed = true
	} else {
		*v.p = append(*v.p, parts...)
	}
	return nil
}
func (v *stringSliceValue) Type() string { return "stringSlice" }

// stringArrayValue accumulates raw values without splitting on commas.
type stringArrayValue struct {
	p       *[]string
	changed bool
}

func (v *stringArrayValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v *stringArrayValue) Set(s string) error {
	if !v.changed {
		*v.p = []string{s}
		v.changed = true
	} else {
		*v.p = append(*v.p, s)
	}
	return nil
}
func (v *stringArrayValue) Type() string { return "stringArray" }

func readAsCSV(s string) ([]string, error) {
	if s == "" {
		return nil, nil
	}
	var (
		out   []string
		field strings.Builder
		inQ   bool
	)
	for i := 0; i < len(s); i++ {
		switch c := s[i]; {
		case c == '"' && inQ && i+1 < len(s) && s[i+1] == '"':
			field.WriteByte('"')
			i++
		case c == '"':
			inQ = !inQ
		case c == ',' && !inQ:
			out = append(out, field.String())
			field.Reset()
		default:
			field.WriteByte(c)
		}
	}
	out = append(out, field.String())
	return out, nil
}

