}
func (v *durationValue) Type() string { return "duration" }

// stringSliceValue accumulates values across repeated occurrences and splits
// each occurrence on commas, mirroring the CSV-style slice flags.
type stringSliceValue struct {
	p       *[]string
	changed bool
}

func (v *stringSliceValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v *stringSliceValue) Set(s string) error {
	parts, err := readAsCSV(s)
	if err != nil {
		return err
	}
	if !v.changed {
		*v.p = parts
		v.changed = true
	} else {
		*v.p = append(*v.p, parts...)
	}
	return nil
}
func (v *stringSliceValue) Type() string { return "stringSlice" }

// stringArrayValue accumulates raw values without splitting on commas.
type stringArrayValue struct {
	p       *[]string
	changed bool
}

func (v *stringArrayValue) String() string { return "[" + strings.Join(*v.p, ",") + "]" }
func (v *stringArrayValue) Set(s string) error {
	if !v.changed {
		*v.p = []string{s}
		v.changed = true
	} else {
		*v.p = append(*v.p, s)
	}
	return nil
}
func (v *stringArrayValue) Type() string { return "stringArray" }

func readAsCSV(s string) ([]string, error) {
	if s == "" {
		return nil, nil
	}
	var (
		out   []string
		field strings.Builder
		inQ   bool
	)
	for i := 0; i < len(s); i++ {
		switch c := s[i]; {
		case c == '"' && inQ && i+1 < len(s) && s[i+1] == '"':
			field.WriteByte('"')
			i++
		case c == '"':
			inQ = !inQ
		case c == ',' && !inQ:
			out = append(out, field.String())
			field.Reset()
		default:
			field.WriteByte(c)
		}
	}
	out = append(out, field.String())
	return out, nil
}

