package cli

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

// Command is a node in the command tree.
type Command struct {
	// Use is the one-line usage, beginning with the command's own name.
	Use string
	// Short is the one-line description shown in a parent's command list.
	Short string
	// Long is the description shown at the top of the command's own help.
	Long string
	// Example is rendered verbatim under an "Examples:" heading.
	Example string
	// Aliases are alternative names accepted for this command.
	Aliases []string
	// Hidden keeps the command out of help listings.
	Hidden bool
	// RunE executes the command. A nil RunE makes the command a pure group.
	RunE func(cmd *Command, args []string) error
	// Args validates the positional arguments.
	Args func(cmd *Command, args []string) error
	// PersistentPreRunE runs before RunE, for this command and its children.
	PersistentPreRunE func(cmd *Command, args []string) error
	// SilenceUsage suppresses the usage block when RunE returns an error.
	SilenceUsage bool
	// SilenceErrors suppresses printing of the error returned by RunE.
	SilenceErrors bool
	// DisableFlagParsing passes the raw arguments straight through.
	DisableFlagParsing bool

	flags     *FlagSet
	pflags    *FlagSet
	parent    *Command
	children  []*Command
	out       io.Writer
	errOut    io.Writer
	helpAsked bool
}

// Name is the first word of Use.
func (c *Command) Name() string {
	if i := strings.IndexByte(c.Use, ' '); i >= 0 {
		return c.Use[:i]
	}
	return c.Use
}

// CommandPath is the space-separated chain of names from the root.
func (c *Command) CommandPath() string {
	if c.parent == nil {
		return c.Name()
	}
	return c.parent.CommandPath() + " " + c.Name()
}

// UseLine is the full invocation line shown under "Usage:".
func (c *Command) UseLine() string {
	var p string
	if c.parent != nil {
		p = c.parent.CommandPath() + " "
	}
	line := p + c.Use
	if !strings.Contains(line, "[flags]") && c.Flags().HasFlags() && !c.hasSubCommands() {
		line += " [flags]"
	}
	return line
}

// Root walks up to the top of the command tree.
func (c *Command) Root() *Command {
	if c.parent == nil {
		return c
	}
	return c.parent.Root()
}

// Parent returns the command's parent, or nil at the root.
func (c *Command) Parent() *Command { return c.parent }

// AddCommand attaches children to c.
func (c *Command) AddCommand(cs ...*Command) {
	for _, sub := range cs {
		sub.parent = c
		c.children = append(c.children, sub)
	}
}

// Commands returns the child commands in declaration order.
func (c *Command) Commands() []*Command { return c.children }

func (c *Command) hasSubCommands() bool {
	for _, sub := range c.children {
		if !sub.Hidden {
			return true
		}
	}
	return false
}

// Flags returns the command's own flag set.
func (c *Command) Flags() *FlagSet {
	if c.flags == nil {
		c.flags = NewFlagSet()
	}
	return c.flags
}

// PersistentFlags returns the flags inherited by the command's descendants.
func (c *Command) PersistentFlags() *FlagSet {
	if c.pflags == nil {
		c.pflags = NewFlagSet()
	}
	return c.pflags
}

// InheritedFlags collects the persistent flags declared by ancestors.
func (c *Command) InheritedFlags() *FlagSet {
	fs := NewFlagSet()
	for p := c.parent; p != nil; p = p.parent {
		if p.pflags != nil {
			for _, f := range p.pflags.flags {
				fs.Add(f)
			}
		}
	}
	return fs
}

// localFlags is the set shown under "Flags:": the command's own flags plus its
// own persistent flags.
func (c *Command) localFlags() *FlagSet {
	fs := NewFlagSet()
	fs.Sorted = c.Flags().Sorted
	if c.pflags != nil {
		for _, f := range c.pflags.flags {
			fs.Add(f)
		}
	}
	for _, f := range c.Flags().flags {
		fs.Add(f)
	}
	return fs
}

// SetOut sets the destination for help and usage output.
func (c *Command) SetOut(w io.Writer) { c.out = w }

// SetErr sets the destination for error output.
func (c *Command) SetErr(w io.Writer) { c.errOut = w }

// OutOrStdout returns the configured output stream.
func (c *Command) OutOrStdout() io.Writer {
	for p := c; p != nil; p = p.parent {
		if p.out != nil {
			return p.out
		}
	}
	return os.Stdout
}

// ErrOrStderr returns the configured error stream.
func (c *Command) ErrOrStderr() io.Writer {
	for p := c; p != nil; p = p.parent {
		if p.errOut != nil {
			return p.errOut
		}
	}
	return os.Stderr
}

// flagLookup finds a flag by long name on the command or any ancestor.
func (c *Command) flagLookup(name string) *Flag {
	if f := c.Flags().Lookup(name); f != nil {
		return f
	}
	if c.pflags != nil {
		if f := c.pflags.Lookup(name); f != nil {
			return f
		}
	}
	for p := c.parent; p != nil; p = p.parent {
		if p.pflags != nil {
			if f := p.pflags.Lookup(name); f != nil {
				return f
			}
		}
	}
	return nil
}

func (c *Command) shorthandLookup(sh string) *Flag {
	if f := c.Flags().short[sh]; f != nil {
		return f
	}
	if c.pflags != nil {
		if f := c.pflags.short[sh]; f != nil {
			return f
		}
	}
	for p := c.parent; p != nil; p = p.parent {
		if p.pflags != nil {
			if f := p.pflags.short[sh]; f != nil {
				return f
			}
		}
	}
	return nil
}

// Find resolves the deepest command addressed by args and returns the remaining
// positional arguments.
func (c *Command) Find(args []string) (*Command, []string) {
	cmd := c
	rest := args
	for len(rest) > 0 {
		arg := rest[0]
		if strings.HasPrefix(arg, "-") {
			break
		}
		sub := cmd.findChild(arg)
		if sub == nil {
			break
		}
		cmd = sub
		rest = rest[1:]
	}
	return cmd, rest
}

func (c *Command) findChild(name string) *Command {
	for _, sub := range c.children {
		if sub.Name() == name {
			return sub
		}
		for _, a := range sub.Aliases {
			if a == name {
				return sub
			}
		}
	}
	return nil
}

// SuggestionsFor returns child command names close to the given typo.
func (c *Command) SuggestionsFor(typedName string) []string {
	var out []string
	for _, sub := range c.children {
		if sub.Hidden {
			continue
		}
		if ld(strings.ToLower(typedName), strings.ToLower(sub.Name()), true) <= 2 ||
			strings.HasPrefix(strings.ToLower(sub.Name()), strings.ToLower(typedName)) {
			out = append(out, sub.Name())
		}
	}
	sort.Strings(out)
	return out
}

// ld is the Levenshtein distance between s and t.
func ld(s, t string, ignoreCase bool) int {
	if ignoreCase {
		s, t = strings.ToLower(s), strings.ToLower(t)
	}
	d := make([][]int, len(s)+1)
	for i := range d {
		d[i] = make([]int, len(t)+1)
		d[i][0] = i
	}
	for j := 0; j <= len(t); j++ {
		d[0][j] = j
	}
	for i := 1; i <= len(s); i++ {
		for j := 1; j <= len(t); j++ {
			cost := 1
			if s[i-1] == t[j-1] {
				cost = 0
			}
			d[i][j] = min3(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+cost)
		}
	}
	return d[len(s)][len(t)]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}

// ExitError carries an explicit process exit status.
type ExitError struct {
	Code int
	Err  error
}

func (e *ExitError) Error() string {
	if e.Err == nil {
		return ""
	}
	return e.Err.Error()
}

// Unwrap exposes the underlying error.
func (e *ExitError) Unwrap() error { return e.Err }

// silentErr suppresses both the message and the usage block, exiting non-zero.
type silentErr struct{}

func (silentErr) Error() string { return "" }

// ErrSilent aborts the command without printing anything extra.
var ErrSilent error = silentErr{}

// Execute parses args, dispatches to the addressed command and returns its
// error after rendering messages the same way the reference CLI does.
func (c *Command) Execute(args []string) error {
	cmd, rest := c.Find(args)
	err := cmd.execute(rest)
	if err == nil {
		return nil
	}
	if _, ok := err.(silentErr); ok {
		return err
	}
	if !cmd.SilenceErrors && !c.SilenceErrors {
		fmt.Fprintln(cmd.ErrOrStderr(), "Error:", err.Error())
	}
	if !cmd.SilenceUsage && !c.SilenceUsage {
		fmt.Fprint(cmd.ErrOrStderr(), cmd.UsageString())
	}
	return err
}

func (c *Command) execute(args []string) error {
	c.Flags().Add(&Flag{
		Name:        "help",
		Shorthand:   "h",
		Usage:       "help for " + c.Name(),
		Value:       &boolValue{p: &c.helpAsked},
		DefValue:    "false",
		NoOptDefVal: "true",
	})
	var positional []string
	if c.DisableFlagParsing {
		positional = args
	} else {
		var err error
		positional, err = c.parseFlags(args)
		if err != nil {
			return err
		}
	}
	if c.helpAsked {
		fmt.Fprint(c.OutOrStdout(), c.HelpString())
		return nil
	}
	if c.RunE == nil {
		// A group with no action prints its help, as does an unknown
		// subcommand name.
		if len(positional) > 0 {
			name := positional[0]
			err := fmt.Errorf("unknown command %q for %q", name, c.CommandPath())
			if sugg := c.SuggestionsFor(name); len(sugg) > 0 {
				var b strings.Builder
				b.WriteString("\n\nDid you mean this?\n")
				for _, s := range sugg {
					fmt.Fprintf(&b, "\t%v\n", s)
				}
				err = fmt.Errorf("%s%s", err, b.String())
			}
			fmt.Fprintln(c.ErrOrStderr(), "Error:", err.Error())
			fmt.Fprint(c.ErrOrStderr(), c.UsageString())
			return ErrSilent
		}
		fmt.Fprint(c.OutOrStdout(), c.HelpString())
		return nil
	}
	for _, p := range c.chain() {
		if p.PersistentPreRunE != nil {
			if err := p.PersistentPreRunE(c, positional); err != nil {
				return err
			}
			break
		}
	}
	if c.Args != nil {
		if err := c.Args(c, positional); err != nil {
			return err
		}
	}
	return c.RunE(c, positional)
}

// chain lists the command and its ancestors, nearest first.
func (c *Command) chain() []*Command {
	var out []*Command
	for p := c; p != nil; p = p.parent {
		out = append(out, p)
	}
	return out
}

