// remainder. Interspersed flags and positionals are allowed; a bare "--" stops
// flag parsing.
func (c *Command) parseFlags(args []string) ([]string, error) {
	var positional []string
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		switch {
		case s == "--":
			return append(positional, args...), nil
		case strings.HasPrefix(s, "--"):
