			args, err = c.parseLong(s[2:], args)
			if err != nil {
				return nil, err
			}
		case len(s) > 1 && s[0] == '-':
			var err error
			args, err = c.parseShort(s[1:], args)
			if err != nil {
				return nil, err
			}
		default:
			positional = append(positional, s)
		}
	}
	return positional, nil
}

func (c *Command) parseLong(body string, args []string) ([]string, error) {
	name, value, hasValue := strings.Cut(body, "=")
	f := c.flagLookup(name)
	if f == nil {
		return nil, fmt.Errorf("unknown flag: --%s", name)
	}
	switch {
	case hasValue:
	case f.NoOptDefVal != "":
		value = f.NoOptDefVal
	case len(args) > 0:
		value, args = args[0], args[1:]
	default:
		return nil, fmt.Errorf("flag needs an argument: --%s", name)
	}
	if err := f.Value.Set(value); err != nil {
		return nil, fmt.Errorf("invalid argument %q for %q flag: %v", value, flagLabel(f), err)
	}
	f.Changed = true
	return args, nil
}

func (c *Command) parseShort(body string, args []string) ([]string, error) {
