	*p = def
	fs.Add(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: &durationValue{p: p}, DefValue: def.String()})
}

// StringSliceVar declares a repeatable, comma-splitting string flag.
func (fs *FlagSet) StringSliceVar(p *[]string, name, shorthand string, def []string, usage string) {
	*p = def
	d := "[" + strings.Join(def, ",") + "]"
	fs.Add(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: &stringSliceValue{p: p}, DefValue: d})
}

// StringArrayVar declares a repeatable string flag that keeps commas intact.
func (fs *FlagSet) StringArrayVar(p *[]string, name, shorthand string, def []string, usage string) {
	*p = def
	d := "[" + strings.Join(def, ",") + "]"
