// CustomVar declares a flag backed by a caller-provided Value.
func (fs *FlagSet) CustomVar(v Value, name, shorthand, usage string) {
	fs.Add(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: v, DefValue: v.String()})
}

