package cli

import (
	"fmt"
	"strings"
	"time"
)

// Duration aliases time.Duration so callers need not import time just to
// declare a duration flag.
type Duration = time.Duration

// HelpString renders the command's full help page.
func (c *Command) HelpString() string {
	var b strings.Builder
	if desc := c.Long; desc != "" {
		b.WriteString(desc)
		b.WriteString("\n\n")
	} else if c.Short != "" {
		b.WriteString(c.Short)
		b.WriteString("\n\n")
	}
	b.WriteString(c.UsageString())
	return b.String()
}

// UsageString renders the "Usage:" block, including subcommands, examples and
// flags.
func (c *Command) UsageString() string {
	var b strings.Builder
	b.WriteString("Usage:")
	if c.RunE != nil || !c.hasSubCommands() {
		b.WriteString("\n  " + c.UseLine())
	}
	if c.hasSubCommands() {
		b.WriteString("\n  " + c.CommandPath() + " [command]")
	}
	if len(c.Aliases) > 0 {
		b.WriteString("\n\nAliases:\n  " + strings.Join(append([]string{c.Name()}, c.Aliases...), ", "))
	}
	if c.Example != "" {
		b.WriteString("\n\nExamples:\n" + c.Example)
	}
	if c.hasSubCommands() {
		b.WriteString("\n\nAvailable Commands:")
		width := 0
		for _, sub := range c.children {
			if !sub.Hidden && len(sub.Name()) > width {
				width = len(sub.Name())
			}
		}
		for _, sub := range c.children {
			if sub.Hidden {
				continue
			}
			b.WriteString(fmt.Sprintf("\n  %-*s %s", width, sub.Name(), sub.Short))
		}
	}
	if local := c.localFlags(); local.HasFlags() {
		b.WriteString("\n\nFlags:\n" + local.Usages())
		b.WriteString("")
	} else {
		b.WriteString("\n")
	}
	if inherited := c.InheritedFlags(); inherited.HasFlags() {
		b.WriteString("\nGlobal Flags:\n" + inherited.Usages())
	}
	if c.hasSubCommands() {
		b.WriteString(fmt.Sprintf("\nUse \"%s [command] --help\" for more information about a command.\n", c.CommandPath()))
	}
	return b.String()
}

// NoArgs rejects any positional argument.
func NoArgs(cmd *Command, args []string) error {
	if len(args) > 0 {
		return fmt.Errorf("unknown command %q for %q", args[0], cmd.CommandPath())
	}
	return nil
}

// MaximumNArgs allows at most n positional arguments.
func MaximumNArgs(n int) func(*Command, []string) error {
	return func(cmd *Command, args []string) error {
		if len(args) > n {
			return fmt.Errorf("accepts at most %d arg(s), received %d", n, len(args))
		}
		return nil
	}
}

// ExactArgs requires exactly n positional arguments.
func ExactArgs(n int) func(*Command, []string) error {
	return func(cmd *Command, args []string) error {
		if len(args) != n {
			return fmt.Errorf("accepts %d arg(s), received %d", n, len(args))
		}
		return nil
	}
}

// RangeArgs requires between min and max positional arguments.
func RangeArgs(min, max int) func(*Command, []string) error {
	return func(cmd *Command, args []string) error {
		if len(args) < min || len(args) > max {
			return fmt.Errorf("accepts between %d and %d arg(s), received %d", min, max, len(args))
		}
		return nil
	}
}

