)

// Shared flag usage strings. Several commands reuse the exact same text.
const (
	urlUsage     = "[driver://username:password@address/dbname?param=value] select a resource using the URL format"
	desiredUsage = "[driver://username:password@address/dbname?param=value] select a desired state using the URL format"
	devURLUsage  = "[driver://username:password@address/dbname?param=value] select a dev database using the URL format"

	excludeUsage     = "list of glob patterns used to filter resources from applying"
	includeUsage     = "list of glob patterns used to select which resources to keep in inspection"
	schemaUsage      = "set schema names"
	formatUsage      = "Go template to use to format the output"
	dirUsage         = "select migration directory using URL format"
	dirFormatUsage   = "select migration file format"
	lockTimeoutUsage = "set how long to wait for the database lock"

	defaultDirURL      = "file://migrations"
	defaultLockTimeout = 10 * time.Second
)

// globalFlags holds the values of the flags shared by the schema and migrate
// command groups.
type globalFlags struct {
	ConfigURL string
	Env       string
	Vars      VarArgs
}

// VarArgs collects repeated --var name=value assignments.
type VarArgs struct {
	Names  []string
	Values map[string]string
	// Repeated records values given more than once for the same name.
	Repeated map[string][]string
}

// String renders the default shown in help output.
func (v *VarArgs) String() string { return "[]" }

// Type is the placeholder used by help output.
func (v *VarArgs) Type() string { return "vars" }

// Set records a single name=value assignment.
func (v *VarArgs) Set(s string) error {
	name, value, ok := strings.Cut(s, "=")
	if !ok {
		return fmt.Errorf("variable %q must be format as key=value", s)
	}
	if v.Values == nil {
		v.Values = map[string]string{}
		v.Repeated = map[string][]string{}
	}
	if _, exists := v.Values[name]; !exists {
		v.Names = append(v.Names, name)
	}
	v.Values[name] = value
	v.Repeated[name] = append(v.Repeated[name], value)
	return nil
}

// gflags is the process-wide instance of the shared flags, mirroring the way the
// reference CLI keeps a single project-file selection.
var gflags globalFlags

// addGlobalFlags declares -c/--config, --env and --var on a command group.
func addGlobalFlags(cmd *cli.Command) {
	fs := cmd.PersistentFlags()
	fs.StringVar(&gflags.ConfigURL, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	fs.StringVar(&gflags.Env, "env", "", "", "set which env from the config file to use")
	fs.CustomVar(&gflags.Vars, "var", "", "input variables")
}

// Root builds the whole command tree.
func Root() *cli.Command {
	root := &cli.Command{
		Use:           "atlas",
		Short:         "Manage your database schema as code",
		SilenceUsage:  true,
		SilenceErrors: true,
	}
	root.AddCommand(
		completionCmd(),
		helpCmd(root),
		licenseCmd(),
		migrateCmd(),
		schemaCmd(),
		versionCmd(),
	)
	return root
}

// Main runs the CLI and returns the process exit status.
func Main(args []string) int {
	root := Root()
	err := root.Execute(args)
	if err == nil {
		return 0
	}
	if _, ok := err.(interface{ silent() }); ok {
		return 1
	}
	if err == cli.ErrSilent {
		return 1
	}
	if ee, ok := err.(*cli.ExitError); ok {
		if ee.Err != nil && ee.Err.Error() != "" {
			fmt.Fprintln(os.Stderr, "Error:", ee.Err.Error())
		}
		return ee.Code
	}
	return 1
}

