package cli

import (
	"fmt"
	"sort"
	"strings"
)

// stripFlags returns the positional words of args, skipping flags and the values
// they consume. It is used to locate subcommand names among interspersed flags.
func stripFlags(args []string, c *Command) []string {
	var words []string
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		switch {
		case s == "--":
			return words
		case strings.HasPrefix(s, "--") && !strings.Contains(s, "=") && !c.longTakesNoValue(s[2:]):
			if len(args) <= 1 {
				return words
			}
			args = args[1:]
		case strings.HasPrefix(s, "-") && !strings.Contains(s, "=") && len(s) == 2 && !c.shortTakesNoValue(s[1:]):
			if len(args) <= 1 {
				return words
			}
			args = args[1:]
		case s != "" && !strings.HasPrefix(s, "-"):
			words = append(words, s)
		}
	}
	return words
}

func (c *Command) longTakesNoValue(name string) bool {
	f := c.flagLookup(name)
	return f != nil && f.NoOptDefVal != ""
}

func (c *Command) shortTakesNoValue(sh string) bool {
	f := c.shorthandLookup(sh)
	return f != nil && f.NoOptDefVal != ""
}

// argsMinusFirstX removes the first standalone occurrence of x from args.
func argsMinusFirstX(args []string, x string) []string {
	for i, a := range args {
		if a == x {
			out := make([]string, 0, len(args)-1)
			out = append(out, args[:i]...)
			out = append(out, args[i+1:]...)
			return out
		}
	}
	return args
}

// Find resolves the deepest command addressed by args. The returned error
// reports an unknown top-level command.
func (c *Command) Find(args []string) (*Command, []string, error) {
	var walk func(*Command, []string) (*Command, []string)
	walk = func(cur *Command, rest []string) (*Command, []string) {
		words := stripFlags(rest, cur)
		if len(words) == 0 {
			return cur, rest
		}
		if sub := cur.findChild(words[0]); sub != nil {
			return walk(sub, argsMinusFirstX(rest, words[0]))
		}
		return cur, rest
	}
	found, rest := walk(c, args)
	if found.Args == nil {
		return found, rest, legacyArgs(found, stripFlags(rest, found))
	}
	return found, rest, nil
}

// legacyArgs is the default positional-argument check: only the root command
// rejects unrecognized words.
func legacyArgs(cmd *Command, args []string) error {
	if !cmd.hasSubCommands() {
		return nil
	}
	if cmd.parent == nil && len(args) > 0 {
		return fmt.Errorf("unknown command %q for %q%s", args[0], cmd.CommandPath(), cmd.suggestionsString(args[0]))
	}
	return nil
}

// suggestionsString renders the "Did you mean this?" block for a typo.
func (c *Command) suggestionsString(typedName string) string {
	sugg := c.SuggestionsFor(typedName)
	if len(sugg) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("\n\nDid you mean this?\n")
	for _, s := range sugg {
		fmt.Fprintf(&b, "\t%v\n", s)
	}
	return b.String()
}

// SuggestionsFor returns child command names close to the given typo.
func (c *Command) SuggestionsFor(typedName string) []string {
	var out []string
	for _, sub := range c.children {
		if sub.Hidden {
			continue
		}
		if ld(typedName, sub.Name(), true) <= 2 ||
			strings.HasPrefix(strings.ToLower(sub.Name()), strings.ToLower(typedName)) {
			out = append(out, sub.Name())
		}
	}
	return out
}

// MarkFlagRequired records that the named flag must be provided.
func (c *Command) MarkFlagRequired(names ...string) {
	c.required = append(c.required, names...)
}

// validateRequiredFlags reports any required flag left unset.
func (c *Command) validateRequiredFlags() error {
	var missing []string
	for _, name := range c.required {
		if f := c.flagLookup(name); f != nil && !f.Changed {
			missing = append(missing, name)
		}
	}
	if len(missing) == 0 {
		return nil
	}
	sort.Strings(missing)
	quoted := make([]string, len(missing))
	for i, m := range missing {
		quoted[i] = fmt.Sprintf("%q", m)
	}
	return fmt.Errorf("required flag(s) %s not set", strings.Join(quoted, ", "))
}

